=== src/main/java/com/tainted/authuser/social/GoogleIdTokenVerifier.java ===
     1	package com.tainted.authuser.social;
     2	
     3	import com.auth0.jwk.Jwk;
     4	import com.auth0.jwk.JwkProvider;
     5	import com.auth0.jwt.JWT;
     6	import com.auth0.jwt.algorithms.Algorithm;
     7	import com.auth0.jwt.interfaces.DecodedJWT;
     8	import com.tainted.authuser.error.InvalidTokenException;
     9	
    10	import java.security.interfaces.RSAPublicKey;
    11	
    12	/**
    13	 * Google OIDC ID-token 검증기. providerToken 은 Google 이 발급한 ID token(JWT).
    14	 * Google JWKS 에서 kid 에 해당하는 공개키를 받아 서명을 검증하고, aud(=clientId)와
    15	 * iss 를 확인한 뒤 sub 로 외부 신원을 구성한다. 외부 네트워크는 JWKS 키 조회뿐(캐시).
    16	 */
    17	public class GoogleIdTokenVerifier implements SocialVerifier {
    18	
    19	    private final JwkProvider jwkProvider;
    20	    private final String clientId;
    21	
    22	    public GoogleIdTokenVerifier(JwkProvider jwkProvider, String clientId) {
    23	        this.jwkProvider = jwkProvider;
    24	        this.clientId = clientId;
    25	    }
    26	
    27	    @Override
    28	    public ExternalIdentity verify(String provider, String providerToken) {
    29	        if (providerToken == null || providerToken.isBlank()) {
    30	            throw new InvalidTokenException("empty google id token");
    31	        }
    32	        try {
    33	            DecodedJWT decoded = JWT.decode(providerToken);
    34	            Jwk jwk = jwkProvider.get(decoded.getKeyId());
    35	            Algorithm algorithm = Algorithm.RSA256((RSAPublicKey) jwk.getPublicKey(), null);
    36	            DecodedJWT verified = JWT.require(algorithm)
    37	                    .withIssuer("https://accounts.google.com", "accounts.google.com")
    38	                    .withAudience(clientId)
    39	                    .build()
    40	                    .verify(providerToken);
    41	            String sub = verified.getSubject();
    42	            if (sub == null || sub.isBlank()) {
    43	                throw new InvalidTokenException("google id token has no subject");
    44	            }
    45	            return new ExternalIdentity("google", "google:" + sub);
    46	        } catch (InvalidTokenException e) {
    47	            throw e;
    48	        } catch (Exception e) {
    49	            throw new InvalidTokenException("google id token verification failed: " + e.getMessage());
    50	        }
    51	    }
    52	}
