    13	 * 서버에서 code 를 access token 으로 교환(client_secret 사용)한 뒤 user/me 로 식별자를 얻는다.
    14	 * 두 번의 외부 호출(token, userinfo)이 일어나는 코드 경로다.
    15	 */
    16	public class KakaoCodeVerifier implements SocialVerifier {
    17	
    18	    static final String TOKEN_URL = "https://kauth.kakao.com/oauth/token";
    19	    static final String USERINFO_URL = "https://kapi.kakao.com/v2/user/me";
    20	
    21	    private final RestClient restClient;
    22	    private final SocialProperties.Provider config;
    23	
    24	    public KakaoCodeVerifier(RestClient restClient, SocialProperties.Provider config) {
    25	        this.restClient = restClient;
    26	        this.config = config;
    27	    }
    28	
    29	    @Override
    30	    public ExternalIdentity verify(String provider, String providerToken) {
    31	        if (providerToken == null || providerToken.isBlank()) {
    32	            throw new InvalidTokenException("empty kakao authorization code");
    33	        }
    34	        try {
    35	            MultiValueMap<String, String> form = new LinkedMultiValueMap<>();
    36	            form.add("grant_type", "authorization_code");
    37	            form.add("client_id", config.getClientId());
    38	            if (config.getClientSecret() != null && !config.getClientSecret().isBlank()) {
    39	                form.add("client_secret", config.getClientSecret());
    40	            }
    41	            form.add("redirect_uri", config.getRedirectUri());
    42	            form.add("code", providerToken);
    43	
    44	            JsonNode tokenResponse = restClient.post()
    45	                    .uri(TOKEN_URL)
    46	                    .contentType(MediaType.APPLICATION_FORM_URLENCODED)
    47	                    .body(form)
    48	                    .retrieve()
    49	                    .body(JsonNode.class);
    50	
    51	            String accessToken = tokenResponse == null ? null
    52	                    : tokenResponse.path("access_token").asText(null);
    53	            if (accessToken == null || accessToken.isBlank()) {
    54	                throw new InvalidTokenException("kakao token exchange returned no access_token");
    55	            }
    56	
    57	            JsonNode me = restClient.get()
    58	                    .uri(USERINFO_URL)
    59	                    .header(HttpHeaders.AUTHORIZATION, "Bearer " + accessToken)
    60	                    .retrieve()
    61	                    .body(JsonNode.class);
    62	
    63	            String id = me == null ? null : me.path("id").asText(null);
    64	            if (id == null || id.isBlank() || "null".equals(id)) {
    65	                throw new InvalidTokenException("kakao user/me returned no id");
    66	            }
    67	            return new ExternalIdentity("kakao", "kakao:" + id);
    68	        } catch (InvalidTokenException e) {
    69	            throw e;
    70	        } catch (Exception e) {
    71	            throw new InvalidTokenException("kakao verification failed: " + e.getMessage());
    72	        }
    73	    }
    74	}

