     1	package com.tainted.authuser.config;
     2	
     3	import com.auth0.jwk.GuavaCachedJwkProvider;
     4	import com.auth0.jwk.JwkProvider;
     5	import com.auth0.jwk.UrlJwkProvider;
     6	import com.tainted.authuser.social.CompositeSocialVerifier;
     7	import com.tainted.authuser.social.GoogleIdTokenVerifier;
     8	import com.tainted.authuser.social.KakaoCodeVerifier;
     9	import com.tainted.authuser.social.MockSocialVerifier;
    10	import com.tainted.authuser.social.NaverTokenVerifier;
    11	import com.tainted.authuser.social.SocialProperties;
    12	import com.tainted.authuser.social.SocialVerifier;
    13	import org.springframework.boot.context.properties.EnableConfigurationProperties;
    14	import org.springframework.context.annotation.Bean;
    15	import org.springframework.context.annotation.Configuration;
    16	import org.springframework.context.annotation.Primary;
    17	import org.springframework.http.client.SimpleClientHttpRequestFactory;
    18	import org.springframework.web.client.RestClient;
    19	
    20	import java.net.MalformedURLException;
    21	import java.net.URL;
    22	import java.time.Duration;
    23	
    24	/**
    25	 * 소셜 로그인 빈 와이어링. provider별 실제 검증기를 구성하고 {@link CompositeSocialVerifier}로
    26	 * 묶어 @Primary {@link SocialVerifier} 로 노출한다(AuthService 가 이 빈을 주입받음).
    27	 */
    28	@Configuration
    29	@EnableConfigurationProperties(SocialProperties.class)
    30	public class SocialConfig {
    31	
    32	    private static final String GOOGLE_JWKS_URL = "https://www.googleapis.com/oauth2/v3/certs";
    33	
    34	    /** Kakao/Naver userinfo 호출용 HTTP 클라이언트(타임아웃 지정). */
    35	    @Bean
    36	    public RestClient socialRestClient() {
    37	        SimpleClientHttpRequestFactory factory = new SimpleClientHttpRequestFactory();
    38	        factory.setConnectTimeout((int) Duration.ofSeconds(3).toMillis());
    39	        factory.setReadTimeout((int) Duration.ofSeconds(5).toMillis());
    40	        return RestClient.builder().requestFactory(factory).build();
    41	    }
    42	
    43	    /** Google JWKS(공개키) 캐시 제공자. */
    44	    @Bean
    45	    public JwkProvider googleJwkProvider() {
    46	        try {
    47	            return new GuavaCachedJwkProvider(new UrlJwkProvider(new URL(GOOGLE_JWKS_URL)));
    48	        } catch (MalformedURLException e) {
    49	            throw new IllegalStateException("invalid google jwks url", e);
    50	        }
    51	    }
    52	
    53	    @Bean
    54	    @Primary
    55	    public SocialVerifier socialVerifier(SocialProperties props, MockSocialVerifier mock,
    56	                                         JwkProvider googleJwkProvider, RestClient socialRestClient) {
    57	        SocialVerifier google = new GoogleIdTokenVerifier(googleJwkProvider, props.getGoogle().getClientId());
    58	        SocialVerifier kakao = new KakaoCodeVerifier(socialRestClient, props.getKakao());
    59	        SocialVerifier naver = new NaverTokenVerifier(socialRestClient, props.getNaver());
    60	        return new CompositeSocialVerifier(props, mock, google, kakao, naver);
    61	    }
    62	}
