     3	import com.tainted.authuser.id.IdGenerator;
     4	import org.springframework.beans.factory.annotation.Value;
     5	import org.springframework.data.redis.core.StringRedisTemplate;
     6	import org.springframework.stereotype.Service;
     7	import java.time.Duration;
     8	import java.util.Optional;
     9	
    10	@Service
    11	public class TokenService {
    12	
    13	    private static final String PREFIX = "auth:token:";
    14	
    15	    private final StringRedisTemplate redis;
    16	    private final IdGenerator idGenerator;
    17	    private final long ttlSeconds;
    18	
    19	    public TokenService(StringRedisTemplate redis,
    20	                        IdGenerator idGenerator,
    21	                        @Value("${auth.token-ttl-seconds}") long ttlSeconds) {
    22	        this.redis = redis;
    23	        this.idGenerator = idGenerator;
    24	        this.ttlSeconds = ttlSeconds;
    25	    }
    26	
    27	    /** userId 에 대한 새 토큰을 발급하고 Redis 에 TTL 과 함께 저장. */
    28	    public String issue(String userId) {
    29	        String token = idGenerator.newId();
    30	        redis.opsForValue().set(PREFIX + token, userId, Duration.ofSeconds(ttlSeconds));
    31	        return token;
    32	    }
    33	
    34	    /** 토큰에 매핑된 userId 를 조회. 없거나 만료면 empty. */
    35	    public Optional<String> resolveUserId(String token) {
    36	        if (token == null || token.isBlank()) {
    37	            return Optional.empty();
    38	        }
    39	        return Optional.ofNullable(redis.opsForValue().get(PREFIX + token));
    40	    }
    41	}

