package com.tainted.authuser.blackbox;

import io.restassured.RestAssured;
import io.restassured.http.ContentType;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.TestInfo;
import org.junit.jupiter.api.TestInstance;
import org.junit.jupiter.api.parallel.Execution;
import org.junit.jupiter.api.parallel.ExecutionMode;

import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.Statement;
import java.util.Map;

import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.equalTo;
import static org.hamcrest.Matchers.matchesPattern;
import static org.hamcrest.Matchers.startsWith;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Black-Box API Integration Test
 *
 * @target-controller AuthController (src/main/java/com/tainted/authuser/web/AuthController.java)
 * @target-api POST /api/v1/auth/login
 *
 * WireMock: 사용하지 않음. AuthService.login → CompositeSocialVerifier 는 provider별
 * social.{provider}.mode 프로퍼티가 "real"일 때만 실제 OAuth 서버(Google JWKS,
 * Kakao/Naver REST)를 호출한다(SocialConfig 참고). application.yml 의 기본값은 전부
 * mode=mock 이며, 이 테스트가 겨냥하는 기본 테스트 서버 구동 방식(환경변수
 * SOCIAL_*_MODE 미설정)에서는 항상 MockSocialVerifier 로 위임되어 외부 HTTP 호출이
 * 발생하지 않는다(detect-external-calls 산출물: external_calls=[] 로 확인).
 * 또한 kakao/naver 검증기가 참조하는 kauth.kakao.com / kapi.kakao.com /
 * openapi.naver.com 호스트는 소스에 하드코딩되어 있어(WireMock 은 localhost만
 * 가로챌 수 있음) mode=real 경로는 애초에 WireMock 으로 테스트 불가능한 케이스다.
 */
@TestInstance(TestInstance.Lifecycle.PER_METHOD)
@Execution(ExecutionMode.CONCURRENT)
class AuthLoginBlackBoxTest {

    private static final String BASE_URL = System.getProperty("test.server.url", "http://localhost:8081");

    private static final String DB_URL = System.getProperty("test.db.url", "jdbc:mysql://localhost:3306/authuser");
    private static final String DB_USER = System.getProperty("test.db.user", "root");
    private static final String DB_PASSWORD = System.getProperty("test.db.password", "rootpw");

    private static final String UUID_PATTERN =
            "^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$";

    // 병렬 안전: 각 SQL 실행마다 독립 Connection을 사용
    private static Connection getDbConnection() throws Exception {
        return DriverManager.getConnection(DB_URL, DB_USER, DB_PASSWORD);
    }

    // 메서드별 고유 ID 생성 (결정적 — 메서드명 기반)
    private String testId(TestInfo info) {
        return String.format("T%09d",
                Math.abs(info.getTestMethod().get().getName().hashCode()) % 1_000_000_000);
    }

    private static void executeSqlTemplate(String resourcePath, Map<String, String> params) {
        try (Connection conn = getDbConnection();
             InputStream is = AuthLoginBlackBoxTest.class
                     .getClassLoader().getResourceAsStream(resourcePath);
             Statement stmt = conn.createStatement()) {
            String sql = new String(is.readAllBytes(), StandardCharsets.UTF_8);
            for (var entry : params.entrySet()) {
                sql = sql.replace("${" + entry.getKey() + "}", entry.getValue());
            }
            for (String line : sql.split("\n")) {
                String trimmed = line.trim();
                if (trimmed.startsWith("--") || trimmed.isEmpty()) continue;
                if (trimmed.endsWith(";")) trimmed = trimmed.substring(0, trimmed.length() - 1);
                if (!trimmed.isEmpty()) stmt.execute(trimmed);
            }
        } catch (Exception e) {
            throw new RuntimeException("SQL template execution failed: " + resourcePath, e);
        }
    }

    private static int countUserAccount(String provider, String externalId) throws Exception {
        try (Connection conn = getDbConnection();
             PreparedStatement ps = conn.prepareStatement(
                     "SELECT COUNT(*) FROM user_account WHERE social_provider = ? AND external_id = ?")) {
            ps.setString(1, provider);
            ps.setString(2, externalId);
            try (ResultSet rs = ps.executeQuery()) {
                assertTrue(rs.next());
                return rs.getInt(1);
            }
        }
    }

    private static String fetchUserAccountId(String provider, String externalId) throws Exception {
        try (Connection conn = getDbConnection();
             PreparedStatement ps = conn.prepareStatement(
                     "SELECT id, created_at FROM user_account WHERE social_provider = ? AND external_id = ?")) {
            ps.setString(1, provider);
            ps.setString(2, externalId);
            try (ResultSet rs = ps.executeQuery()) {
                assertTrue(rs.next());
                assertNotNull(rs.getTimestamp("created_at"));
                return rs.getString("id");
            }
        }
    }

    // ==================== NTC: Happy Path ====================

    @Test
    void NTC_login_google_newUser_success(TestInfo info) throws Exception {
        String id = testId(info);
        String provider = "google";
        String externalId = provider + ":" + id;
        String providerToken = "valid-" + provider + "-" + id;

        executeSqlTemplate("sql/auth-login-teardown.sql", Map.of("PROVIDER", provider, "EXTERNAL_ID", externalId));

        try {
            given().log().all()
                    .baseUri(BASE_URL)
                    .contentType(ContentType.JSON)
                    .body("{\"provider\":\"" + provider + "\",\"providerToken\":\"" + providerToken + "\"}")
            .when()
                    .post("/api/v1/auth/login")
            .then().log().all()
                    .statusCode(200)
                    .body("accessToken", matchesPattern(UUID_PATTERN))
                    .body("displayName", equalTo("익명"));

            assertEquals(1, countUserAccount(provider, externalId));
            String createdId = fetchUserAccountId(provider, externalId);
            assertNotNull(createdId);
            assertTrue(createdId.matches(UUID_PATTERN), "generated user id should be a UUID: " + createdId);
        } finally {
            executeSqlTemplate("sql/auth-login-teardown.sql", Map.of("PROVIDER", provider, "EXTERNAL_ID", externalId));
        }
    }

    @Test
    void NTC_login_kakao_newUser_success(TestInfo info) throws Exception {
        String id = testId(info);
        String provider = "kakao";
        String externalId = provider + ":" + id;
        String providerToken = "valid-" + provider + "-" + id;

        executeSqlTemplate("sql/auth-login-teardown.sql", Map.of("PROVIDER", provider, "EXTERNAL_ID", externalId));

        try {
            given().log().all()
                    .baseUri(BASE_URL)
                    .contentType(ContentType.JSON)
                    .body("{\"provider\":\"" + provider + "\",\"providerToken\":\"" + providerToken + "\"}")
            .when()
                    .post("/api/v1/auth/login")
            .then().log().all()
                    .statusCode(200)
                    .body("accessToken", matchesPattern(UUID_PATTERN))
                    .body("displayName", equalTo("익명"));

            assertEquals(1, countUserAccount(provider, externalId));
        } finally {
            executeSqlTemplate("sql/auth-login-teardown.sql", Map.of("PROVIDER", provider, "EXTERNAL_ID", externalId));
        }
    }

    @Test
    void NTC_login_toss_newUser_success(TestInfo info) throws Exception {
        // "toss" bypasses SocialProperties.modeOf()/pick() entirely (CompositeSocialVerifier
        // always routes it straight to the mock verifier) — distinct branch from google/kakao/naver.
        String id = testId(info);
        String provider = "toss";
        String externalId = provider + ":" + id;
        String providerToken = "valid-" + provider + "-" + id;

        executeSqlTemplate("sql/auth-login-teardown.sql", Map.of("PROVIDER", provider, "EXTERNAL_ID", externalId));

        try {
            given().log().all()
                    .baseUri(BASE_URL)
                    .contentType(ContentType.JSON)
                    .body("{\"provider\":\"" + provider + "\",\"providerToken\":\"" + providerToken + "\"}")
            .when()
                    .post("/api/v1/auth/login")
            .then().log().all()
                    .statusCode(200)
                    .body("accessToken", matchesPattern(UUID_PATTERN))
                    .body("displayName", equalTo("익명"));

            assertEquals(1, countUserAccount(provider, externalId));
        } finally {
            executeSqlTemplate("sql/auth-login-teardown.sql", Map.of("PROVIDER", provider, "EXTERNAL_ID", externalId));
        }
    }

    @Test
    void NTC_login_existingUser_reuse_success(TestInfo info) throws Exception {
        // Exercises the orElseGet "already present" branch: repository.save must NOT be
        // called again, and the pre-existing (fixed) id must be reused for token issuance.
        String id = testId(info);
        String provider = "naver";
        String externalId = provider + ":" + id;
        String providerToken = "valid-" + provider + "-" + id;
        String preExistingId = "PRE-" + id;
        Map<String, String> params = Map.of("ID", preExistingId, "PROVIDER", provider, "EXTERNAL_ID", externalId);

        executeSqlTemplate("sql/auth-login-teardown.sql", params);
        executeSqlTemplate("sql/auth-login-setup.sql", params);

        try {
            given().log().all()
                    .baseUri(BASE_URL)
                    .contentType(ContentType.JSON)
                    .body("{\"provider\":\"" + provider + "\",\"providerToken\":\"" + providerToken + "\"}")
            .when()
                    .post("/api/v1/auth/login")
            .then().log().all()
                    .statusCode(200)
                    .body("accessToken", matchesPattern(UUID_PATTERN))
                    .body("displayName", equalTo("익명"));

            assertEquals(1, countUserAccount(provider, externalId));
            assertEquals(preExistingId, fetchUserAccountId(provider, externalId));
        } finally {
            executeSqlTemplate("sql/auth-login-teardown.sql", params);
        }
    }

    // ==================== ATC: Business Exceptions ====================

    @Test
    void ATC_login_unsupportedProvider_returns401(TestInfo info) throws Exception {
        String id = testId(info);
        String provider = "facebook";
        String externalId = provider + ":" + id;

        executeSqlTemplate("sql/auth-login-teardown.sql", Map.of("PROVIDER", provider, "EXTERNAL_ID", externalId));

        try {
            given().log().all()
                    .baseUri(BASE_URL)
                    .contentType(ContentType.JSON)
                    .body("{\"provider\":\"" + provider + "\",\"providerToken\":\"valid-" + provider + "-" + id + "\"}")
            .when()
                    .post("/api/v1/auth/login")
            .then().log().all()
                    .statusCode(401)
                    .header("Content-Type", startsWith("application/problem+json"))
                    .body("title", equalTo("Invalid token"))
                    .body("detail", equalTo("unsupported provider: " + provider));

            assertEquals(0, countUserAccount(provider, externalId));
        } finally {
            executeSqlTemplate("sql/auth-login-teardown.sql", Map.of("PROVIDER", provider, "EXTERNAL_ID", externalId));
        }
    }

    @Test
    void ATC_login_malformedToken_returns401(TestInfo info) throws Exception {
        String id = testId(info);
        String provider = "google";
        String externalId = provider + ":" + id;
        // Does not start with "valid-google-" -> MockSocialVerifier malformed-token branch.
        String providerToken = "not-the-expected-format-" + id;

        executeSqlTemplate("sql/auth-login-teardown.sql", Map.of("PROVIDER", provider, "EXTERNAL_ID", externalId));

        try {
            given().log().all()
                    .baseUri(BASE_URL)
                    .contentType(ContentType.JSON)
                    .body("{\"provider\":\"" + provider + "\",\"providerToken\":\"" + providerToken + "\"}")
            .when()
                    .post("/api/v1/auth/login")
            .then().log().all()
                    .statusCode(401)
                    .header("Content-Type", startsWith("application/problem+json"))
                    .body("title", equalTo("Invalid token"))
                    .body("detail", equalTo("malformed token for provider: " + provider));

            assertEquals(0, countUserAccount(provider, externalId));
        } finally {
            executeSqlTemplate("sql/auth-login-teardown.sql", Map.of("PROVIDER", provider, "EXTERNAL_ID", externalId));
        }
    }

    @Test
    void ATC_login_emptySeed_returns401(TestInfo info) throws Exception {
        String provider = "kakao";
        // Valid prefix but empty seed portion -> MockSocialVerifier "empty seed" branch.
        String providerToken = "valid-" + provider + "-";

        given().log().all()
                .baseUri(BASE_URL)
                .contentType(ContentType.JSON)
                .body("{\"provider\":\"" + provider + "\",\"providerToken\":\"" + providerToken + "\"}")
        .when()
                .post("/api/v1/auth/login")
        .then().log().all()
                .statusCode(401)
                .header("Content-Type", startsWith("application/problem+json"))
                .body("title", equalTo("Invalid token"))
                .body("detail", equalTo("empty seed"));
    }

    // ==================== VTC: RED-parameter mutation (provider) ====================
    // RED: `provider` drives the CompositeSocialVerifier switch branch (BRANCH_CONDITION)
    // and (on success) becomes the persisted social_provider column value.

    @Test
    void VTC_provider_NULL(TestInfo info) throws Exception {
        // Also satisfies test-plan checklist item ATC_code400 (General Bad Request).
        String id = testId(info);
        given().log().all()
                .baseUri(BASE_URL)
                .contentType(ContentType.JSON)
                .body("{\"providerToken\":\"valid-google-" + id + "\"}")
        .when()
                .post("/api/v1/auth/login")
        .then().log().all()
                .statusCode(400)
                .header("Content-Type", startsWith("application/problem+json"));
    }

    @Test
    void VTC_provider_EMPTY(TestInfo info) throws Exception {
        String id = testId(info);
        given().log().all()
                .baseUri(BASE_URL)
                .contentType(ContentType.JSON)
                .body("{\"provider\":\"\",\"providerToken\":\"valid-google-" + id + "\"}")
        .when()
                .post("/api/v1/auth/login")
        .then().log().all()
                .statusCode(400)
                .header("Content-Type", startsWith("application/problem+json"));
    }

    @Test
    void VTC_provider_WHITE_SPACE(TestInfo info) throws Exception {
        String id = testId(info);
        given().log().all()
                .baseUri(BASE_URL)
                .contentType(ContentType.JSON)
                .body("{\"provider\":\"   \",\"providerToken\":\"valid-google-" + id + "\"}")
        .when()
                .post("/api/v1/auth/login")
        .then().log().all()
                .statusCode(400)
                .header("Content-Type", startsWith("application/problem+json"));
